  const n2 = Math.sin(y*0.011-t*0.19)*Math.cos(x*0.014+t*0.11);
  const n3 = Math.sin((x+y)*0.009+t*0.23)*Math.cos((x-y)*0.012-t*0.15);
  const wx = n1*18 + n2*12 + n3*8;
  const wy = n2*18 + n3*12 + n1*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [120+Math.sin(t*0.31)*110, 60+Math.cos(t*0.23)*40, 0.065, 1.8],
    [360+Math.cos(t*0.27)*100, 80+Math.sin(t*0.37)*50, 0.08, 2.1],
